targets.query:
import "strings"
from(bucket: "telemetry")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "engine" and (r._field == "dtc_text"))
  |> filter(fn: (r) => r.vessel == "${vessel}")
  |> map(fn: (r) => {
      parts = strings.split(v: r._value, t: "; ")
      n = length(arr: parts)
      return {r with _value: if n > 1 then parts[0] + " (+" + string(v: n - 1) + " more)" else r._value}
  })
  |> last()
  |> drop(fn: (column) => column =~ /^(_start|_stop|_measurement|vessel|host|instance|source|engine_type|engine_model)$/)
  |> keep(columns: ["_value"])
